      SUBROUTINE RDVCEXC---- CONVERT INTERNAL VARY CODES TO EXTERNALC---------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA1B.CIN'      INCLUDE 'DATA1C.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'DATA2B.CIN'      INCLUDE 'DATA2D.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'INSERT.CIN'      INCLUDE 'IOFLAG.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'RDPRNT.CIN'      INCLUDE 'RDWRDS.CIN'C-----------------------------------------------------------------------      EXTERNAL        IDATAC-----------------------------------------------------------------------CC     CONVERT EXTERNAL VARY CODES TO INTERNALC      IF (FLUSHL) GO TO 220      DO 210 NUM = 1, NEL      I = ISTOR(NUM)      NTYPE = IDATA(I)      IF (NTYPE .LE. 0 .OR. NTYPE .GE. 50) GO TO 210      IF (NTYPE .EQ. 10) GO TO 210      IBEG = I + 1      IEND = ISTOR(NUM+1) - 1      DO 208 I = IBEG, IEND      K = IABS(TIE(I))      IF (K .NE. 0 .AND. K .LT. 99) TIE(I) = ISIGN(VSTOR(K), TIE(I))  205 CONTINUE  208 CONTINUE  210 CONTINUECC     MODIFY EXISTING SYSTEMC  220 NUM = 0      REMOVE = .FALSE.      INSERT = .FALSE.  230 CALL RDELMT      IF (ENDFIL) GO TO 500      IF (NTYPE .NE. 73) GO TO 230CC     OPTIONALLY PRINT MODIFIED SYSTEMC  400 IF (INDS .EQ. 0) GO TO 500      IF (.NOT. LIST .OR. .NOT. RFM) GO TO 450      DO 401 NUM = 1, NEL      IPI = 0      I = IABS(ISTOR(NUM))      CALL SKETCH(NUM)      NWORD = NPARMS + 1      IF (I .NE. ISTOR(NUM)) THEN        IPI = 1        ISTOR(NUM) = I      ENDIF      CALL PRINT1(LABEL(NUM),NWORD,DATA(I),TIE(I),IPI)  401 CONTINUECC     WRITE SYSTEM ONTO DISKC  450 IF (.NOT. BWT) GO TO 500      NELP1 = NEL + 1      IEL = ISTOR(NELP1) - 1      WRITE (NDATA) NEL, IEL      WRITE (NDATA) (DATA(I), I = 1, IEL)      WRITE (NDATA) (TIE(I), I = 1, IEL)      WRITE (NDATA) (ISTOR(N), N = 1, NELP1)      WRITE (NDATA) (NDESCR(N), N = 1, NEL)      WRITE (NDATA) (LABEL(N), N = 1, NEL)C  500 CONTINUE      RETURN      END